// Board sounds: a move, a capture, a check and a checkmate.
// The sounds are tiny synthesized wood-tap style clips stored right in this file as base64 WAV data,
// so there are no audio files to ship. Switch them off in Settings > Playing > "Play move sounds".

import { live } from "./settings";

const SOUNDS = {
  move: "",
  capture: "",
  check: "",
  mate: "",
} as const;

export type SoundKind = keyof typeof SOUNDS;

let ctx: AudioContext | null = null;
const buffers: Partial<Record<SoundKind, AudioBuffer>> = {};

function getContext(): AudioContext | null {
  if (!ctx) {
    const AC: typeof AudioContext | undefined =
      window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!AC) return null;
    ctx = new AC();
  }
  return ctx;
}

async function load(c: AudioContext, kind: SoundKind): Promise<AudioBuffer> {
  const cached = buffers[kind];
  if (cached) return cached;
  const bin = atob(SOUNDS[kind]);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const buf = await c.decodeAudioData(bytes.buffer);
  buffers[kind] = buf;
  return buf;
}

/** Phones and browsers keep audio locked until you have touched the page once. */
function unlock() {
  const c = getContext();
  if (!c) return;
  if (c.state === "suspended") c.resume().catch(() => {});
  (Object.keys(SOUNDS) as SoundKind[]).forEach((k) => load(c, k).catch(() => {}));
}

if (typeof window !== "undefined") {
  const events = ["pointerup", "touchend", "click", "keydown"];
  const handler = () => {
    unlock();
    if (ctx && ctx.state === "running") events.forEach((e) => window.removeEventListener(e, handler, true));
  };
  events.forEach((e) => window.addEventListener(e, handler, true));
}

export async function playSound(kind: SoundKind) {
  if (!live.sounds) return;
  try {
    const c = getContext();
    if (!c) return;
    if (c.state === "suspended") await c.resume();
    const src = c.createBufferSource();
    src.buffer = await load(c, kind);
    src.connect(c.destination);
    src.start();
  } catch {
    // no audio available: stay silent
  }
}
